import { defineRouteMiddleware } from '@astrojs/starlight/route-data';

type SidebarEntry = App.Locals['starlightRoute']['sidebar'][number];

// Turn folder names into readable labels: "WolvCTF_2026" -> "WolvCTF 2026".
const prettify = (label: string) => label.replace(/[_-]+/g, ' ').trim();

// Only nested groups (autogenerated from sub-folders) are renamed:
// top-level groups keep the labels set in astro.config.mjs (e.g. "Write-ups").
function renameGroups(entries: SidebarEntry[]) {
	for (const entry of entries) {
		if (entry.type !== 'group') continue;
		entry.label = prettify(entry.label);
		renameGroups(entry.entries);
	}
}

export const onRequest = defineRouteMiddleware((context) => {
	for (const entry of context.locals.starlightRoute.sidebar) {
		if (entry.type === 'group') renameGroups(entry.entries);
	}
});
